"use client";

import Image from "next/image";
import { useEffect, useState } from "react";

const menu = [
  "Business Setup",
  "Tax & Compliance",
  "IP & Trademarks",
  "Legal Documents",
  "Licenses",
  "Experts",
];

export function Header() {
  const [open, setOpen] = useState(false);
  const [scrolled, setScrolled] = useState(false);

  useEffect(() => {
    const handleScroll = () => {
      setScrolled(window.scrollY > 28);
    };

    handleScroll();

    window.addEventListener("scroll", handleScroll, { passive: true });

    return () => window.removeEventListener("scroll", handleScroll);
  }, []);

  return (
    <header className={`lx-header ${scrolled ? "lx-header-scrolled" : ""}`}>
      <div className="lx-header-shell">
        <a className="lx-brand" href="#">
          <Image
            src="/lawxygen-logo.jpeg"
            alt="LAWXYGEN"
            width={190}
            height={88}
            priority
            className="lx-brand-image"
          />
        </a>

        <nav className="lx-desktop-nav">
          {menu.map((item) => (
            <a href="#services" key={item}>
              {item}
            </a>
          ))}
        </nav>

        <div className="lx-header-right">
          <a href="#contact" className="lx-nav-cta">
            Consult an Expert
            <span>↗</span>
          </a>

          <button
            className={`lx-menu-button ${open ? "active" : ""}`}
            onClick={() => setOpen(!open)}
            aria-label="Toggle navigation"
            aria-expanded={open}
          >
            <span />
            <span />
          </button>
        </div>
      </div>

      <div className={`lx-mobile-menu ${open ? "active" : ""}`}>
        <div className="lx-mobile-menu-inner">
          {menu.map((item, index) => (
            <a
              href="#services"
              key={item}
              onClick={() => setOpen(false)}
            >
              <span>0{index + 1}</span>
              <strong>{item}</strong>
              <b>↗</b>
            </a>
          ))}

          <a
            href="#contact"
            className="lx-mobile-expert"
            onClick={() => setOpen(false)}
          >
            Talk to an Expert
          </a>
        </div>
      </div>
    </header>
  );
}